    # The key is a row repeated several times; its nonzero entries give
    # the colors in top-to-bottom copy order.
    groups = {}
    for r, row in enumerate(grid):
        if any(row):
            groups.setdefault(tuple(row), []).append(r)
    repeated = [(sig, rs) for sig, rs in groups.items() if len(rs) >= 2]
    if not repeated:
        return [row[:] for row in grid]
    sig, key_rows = max(repeated, key=lambda item: sum(v != 0 for v in item[0]))
    palette = [v for v in sig if v]
    key_cells = {(r, c) for r in key_rows for c in range(w) if grid[r][c]}

    # The center key color marks the shape to replicate. Use diagonal
    # connectivity as the shape may touch only at corners.
    color = palette[len(palette) // 2]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in key_cells or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        yy, xx = y + dy, x + dx
                        if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and (yy, xx) not in key_cells and
                            grid[yy][xx] == color):
                            seen.add((yy, xx))
                            stack.append((yy, xx))
            comps.append(comp)

    if not comps:
        return [row[:] for row in grid]
    shape = max(comps, key=len)
    r0 = min(r for r, c in shape)
    c0 = min(c for r, c in shape)
    dh = max(r for r, c in shape) - r0 + 1
    pattern = {(r - r0, c - c0) for r, c in shape}

    start = r0 - palette.index(color) * dh
    out = [[0] * w for _ in range(h)]
    for i, col in enumerate(palette):
        for dr, dc in pattern:
            rr, cc = start + i * dh + dr, c0 + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = col
    return out
